stringcontrol.script:
function setText(sText, bRed)
	if (sText or "") == "" then
		setVisible(false);
		return;
	end
	setFrame(bRed and "cc_chip_red" or "cc_chip_gold", 8, 3, 8, 3);
	setValue(sText);
	-- Rough width fit for placeholder art; refine once in-app
	setAnchoredWidth(18 + (#sText * 7));
	setVisible(true);
end

genericcontrol.script:
function setIdentity(sIdentity, bGM)
	if (sIdentity or "") ~= "" then
		setIcon("portrait_" .. sIdentity .. "_chat");
	elseif bGM then
		setIcon("cc_portrait_gm");
	else
		setIcon("cc_portrait_unknown");
	end
end
